1190	(G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^\bx_{[g_2(\by_2) = a_2]} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes (G_2)^\bx_{[g_2(\by_2) = a_2]} \ket{\psi}.
1191	\end{equation}
1192	
1193	Now, we compute \Cref{eq:cloud} minus \Cref{eq:strife}:
1194	\begin{align*}
1195	&\E_{\bx, \by_1, \by_2} \sum_{a_1}\sum_{\substack{g_2, g_2'\\g_2(\by_2) \neq g_2'(\by_2)}} \bra{\psi}
1196		 (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes (G_2)^{\bx}_{g_2'} \ket{\psi}\\
1197	=&\E_{\bx, \by_1, \by_2} \sum_{a_1}\sum_{g_2, g_2'} \bra{\psi}
1198		 (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \cdot (G_2)^{\bx}_{g_2} \cdot (G_1)^{\bx}_{[g_1(\by_1) = a_1]} \otimes (G_2)^{\bx}_{g_2'} \ket{\psi}
1199		 	\cdot \bone(g_2, g_2', \by_2),
1200	\end{align*}
1201	where $\bone(g_2, g_2', \by_2)$ is the indicator that $g_2 \neq g_2'$ but $g_2(\by_2) = g_2'(\by_2)$.
1202	This is the only part of the expression that depends on $\by_2$, and by our distance assumption it is at most $\eps$ in expectation.
1203	Since the rest of the expression is guaranteed to be positive, we can upper-bound this by
1204	\begin{equation*}
