   306		\[
   307			V_{\mathrm{A}} = \sum_{g_X,g_Z} (\hat{S}_{g_X,g_Z})_{\mathrm{A}\mathrm{A}'} \ot \bigl(\tau^X(\mathrm{Dec}(g_Z)) \, \tau^Z(\mathrm{Dec}(g_X))\bigr)_{\mathrm{A}''}\;,
