import numpy as np
rng=np.random.default_rng(3)
def trial(n,L,K=250,T=150):
 P=[]
 for i in range(n):
  x=np.zeros((n,n),complex);x[i,i]=1;P.append(x)
 parts=[];counts=np.zeros((n,n))
 for _ in range(K):
  p=rng.permutation(n); bs=[p[i:i+L] for i in range(0,n,L)];parts.append(bs)
  for B in bs: counts[np.ix_(B,B)]+=1
 eta=np.max((counts/K)[~np.eye(n,dtype=bool)])
 worst={.5:0,1:0,2:0,4:0,8:0}
 for _ in range(T):
  z=rng.normal(size=(n,n))+1j*rng.normal(size=(n,n));z=(z+z.conj().T)/2
  _,u=np.linalg.eigh(z); vals=rng.random(n);H=u@np.diag(vals)@u.conj().T
  Fs=np.zeros((n,n),complex); Cs=np.zeros_like(Fs)
  for Ha in [H,np.eye(n)-H]:
   for bs in parts:
    for B in bs:
     Q=sum((P[int(i)] for i in B),np.zeros_like(Fs))
     J=sum((P[int(i)]@Ha@P[int(i)] for i in B),np.zeros_like(Fs))
     D=Q@Ha@Q-J;Fs+=D.conj().T@D/K
     X=Ha@Q-Q@Ha;Cs+=X.conj().T@X/K
  for c in worst:
   lam=np.linalg.eigvalsh(Fs-c*Cs).max().real/eta
   worst[c]=max(worst[c],lam)
 return eta,worst
for n,L in [(4,2),(8,2),(8,4),(12,3),(16,4)]:
 eta,w=trial(n,L)
 print(n,L,round(eta,4),{c:round(v,3) for c,v in w.items()})
PY"

